package com.retail.shipping;
import jakarta.persistence.*; import jakarta.transaction.Transactional; import jakarta.validation.constraints.*; import jakarta.ws.rs.*; import jakarta.ws.rs.core.MediaType; import java.util.*;
@Path("/") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class ShippingResource { @PersistenceContext EntityManager em; public record ShipmentRequest(@NotNull UUID orderId,@NotBlank @Size(max=1000) String address){} public record StatusRequest(@NotBlank String status){}
 @GET @Path("api/ping") @Produces(MediaType.TEXT_PLAIN) public String ping(){return "Hello from Shipping Service";}
 @POST @Path("internal/shipments") @Transactional public Map<String,Object> create(@jakarta.validation.Valid ShipmentRequest r){List<?> q=em.createNativeQuery("select tracking_code,status,address from shipments where order_id=?1").setParameter(1,r.orderId()).getResultList();if(!q.isEmpty()){Object[]v=(Object[])q.getFirst();if(!v[2].equals(r.address()))throw new ClientErrorException("Shipment request conflicts with existing shipment",409);return out(r.orderId(),(String)v[0],(String)v[1]);}String tracking="SHP-"+r.orderId().toString().substring(0,8).toUpperCase();em.createNativeQuery("insert into shipments(order_id,tracking_code,address,status) values(?1,?2,?3,'CREATED')").setParameter(1,r.orderId()).setParameter(2,tracking).setParameter(3,r.address()).executeUpdate();return out(r.orderId(),tracking,"CREATED");}
 @GET @Path("internal/shipments/{orderId}") public Map<String,Object> get(@PathParam("orderId") UUID id){List<?>q=em.createNativeQuery("select tracking_code,status from shipments where order_id=?1").setParameter(1,id).getResultList();if(q.isEmpty())throw new NotFoundException("Shipment not found");Object[]v=(Object[])q.getFirst();return out(id,(String)v[0],(String)v[1]);}
 @POST @Path("internal/shipments/{orderId}/cancel") @Transactional public Map<String,Object> cancel(@PathParam("orderId") UUID id){int n=em.createNativeQuery("update shipments set status='CANCELLED',updated_at=now() where order_id=?1 and status='CREATED'").setParameter(1,id).executeUpdate();if(n==0){Map<String,Object> current=get(id);if(!"CANCELLED".equals(current.get("status")))throw new ClientErrorException("Shipment can no longer be cancelled",409);return current;}return get(id);}
 @POST @Path("internal/shipments/{orderId}/status") @Transactional public Map<String,Object> status(@PathParam("orderId") UUID id,@jakarta.validation.Valid StatusRequest r){if(!Set.of("SHIPPED","DELIVERED").contains(r.status()))throw new BadRequestException("Unsupported shipment status");int n=em.createNativeQuery("update shipments set status=?2,updated_at=now() where order_id=?1 and status in ('CREATED','SHIPPED')").setParameter(1,id).setParameter(2,r.status()).executeUpdate();if(n==0)throw new ClientErrorException("Shipment state transition is invalid",409);return get(id);} private static Map<String,Object> out(UUID id,String code,String status){return Map.of("orderId",id,"trackingCode",code,"status",status);}}
